/**
 * @summary Create or update a translation (admin)
 */
export const getUpsertTranslationUrl = () => {
  return `/api/translations`;
};

export const upsertTranslation = async (
  translationInput: TranslationInput,
  options?: RequestInit,
): Promise<Translation> => {
  return customFetch<Translation>(getUpsertTranslationUrl(), {
    ...options,
    method: "PUT",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(translationInput),
  });
};

export const getUpsertTranslationMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof upsertTranslation>>,
    TError,
    { data: BodyType<TranslationInput> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof upsertTranslation>>,
  TError,
  { data: BodyType<TranslationInput> },
  TContext
> => {
  const mutationKey = ["upsertTranslation"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof upsertTranslation>>,
    { data: BodyType<TranslationInput> }
  > = (props) => {
    const { data } = props ?? {};

    return upsertTranslation(data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type UpsertTranslationMutationResult = NonNullable<
  Awaited<ReturnType<typeof upsertTranslation>>
>;
export type UpsertTranslationMutationBody = BodyType<TranslationInput>;
export type UpsertTranslationMutationError = ErrorType<unknown>;

/**
 * @summary Create or update a translation (admin)
 */
export const useUpsertTranslation = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof upsertTranslation>>,
    TError,
    { data: BodyType<TranslationInput> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationResult<
  Awaited<ReturnType<typeof upsertTranslation>>,
  TError,
  { data: BodyType<TranslationInput> },
  TContext
> => {
  return useMutation(getUpsertTranslationMutationOptions(options));
};
